from collections import Counter

def find_max_raft_area(logs):
    counts = Counter(logs)
    max_area = 0
    for length, count in counts.items():
        for combo in combinations_with_replacement(range(1, length), count):
            for combo2 in combinations_with_replacement(range(1, length), length - count):
                if len(combo) > len(combo2):
                    continue
                area = combo[0] * combo[0] + sum(combo2)
                if area > sum(count) * length:
                    break
                max_area = max(max_area, area)
    return max_area

def combinations_with_replacement(iterable, r):
    pool = tuple(iterable)
    n = len(pool)
    if r == 0:
        return []
    elif r > n:
        return []
    else:
        indices = [0] * r
        yielded = [False] * r
        while True:
            yield tuple(pool[i] for i in indices)
            for i in range(n-1, -1, -1):
                if indices[i] == n-r+i:
                    indices[i] = 0
                    yield from combinations_with_replacement(pool, r)
                else:
                    indices[i] += 1
                    yield from combinations_with_replacement(pool, r)
                    break
            else:
                return

