import sys
from collections import defaultdict

def mod_pow(a, n, mod):
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * a) % mod
        a = (a * a) % mod
        n //= 2
    return result

def find_cycler(a, n, mod):
    if n == 1:
        return a % mod
    elif n % 2 == 1:
        for i in range(n):
            a = (a * a) % mod
            new = (mod_pow(a, i, mod) * mod_pow(a, n - 1 - i, mod)) % mod
            if new == 1: return new
    else:
        for i in range(n):
            a = (a * a) % mod
            new = (mod_pow(a, n // 2, mod) * mod_pow(a, n // 2, mod)) % mod
            if new == 1: return new
    return a

def solve_mmcgers(matrix, n, k):
    n = matrix[0][0]
    initial_elements = []
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if matrix[i][j] != 1:
                initial_elements.append((i, j, matrix[i][j] - 1))
    initial_elements.sort(key=lambda x: x[2])

    count_map = defaultdict(lambda: 0, {x[2]: 0 for x in initial_elements})
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            count_map[matrix[i][j]].append((i, j))

    total = 1
    for i in range(n**2):
        for c in count_map[i]:
            total = (total * c[1]) % 1000000007
    return total

def solve(m, n):
    A = [[1 for _ in range(n)] for _ in range(n)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if m.find(f'{i} {j}') != -1:
                A[i - 1][j - 1] -= 1

    return solve_mmcgers(A, n, 1000000000 + 7)

