from collections import deque

def max_raft_area(log_lengths, n):
    max_area = 0
    max_depth = 2

    # Helper function to find the maximum area using dynamic programming
    def dfs(start, length):
        nonlocal max_area
        if max_area >= length * max_depth:
            return
        for i in range(start, len(log_lengths)):
            if log_lengths[i] >= length - 1:
                end = start + 1
                while end < len(log_lengths) and log_lengths[end] >= length - 1 - log_lengths[i]:
                    end += 1
                area = (length - 1) * (length - 1) - (length - 1 - end) * (length - 1 - end)
                if max_depth >= (end - start + 1):
                    dfs(end, length - 1)
                else:
                    max_area = max(max_area, area)

    # Check for initial conditions
    if log_lengths[0] > max_depth:
        return (log_lengths[0] - 1) * (log_lengths[0] - 1)

    # Check for dual sizes at variable lengths
    for ind in range(2, n):
        if log_lengths[ind] > max_depth:
            break
        if ((log_lengths[ind] + log_lengths[ind - 1]) % 2 == 1):
            continue
        new_depth = (log_lengths[ind] + log_lengths[ind - 1]) // 2
        if 2 * new_depth > max_depth:
            continue
        dfs(1, new_depth)

    # Check for single sizes
    for el in log_lengths[2:]:
        if el >= max_depth:
            bfs(el)

    return max_area

