def solve(m):
    # Build adjacency list for given graph
    graph = {i: [] for i in range(1, m + 1)}
    for _ in range(m):
        a, b = map(int, input().split())
        graph[a].append(b)
        graph[b].append(a)

    # Check subset sums for groups of 4 or 7
    subsetSums = set(range(4, 8))
    subsetNeeded = defaultdict(lambda: False)
    for s in subsetSums:
        subsetNeeded[s] = True

    from collections import deque
    from operator import itemgetter

    def subsumSum(nums, i):
        while i < len(nums) and nums[i] not in subsetSums:
            i += 1
        return nums[i:].count(nums[i])

    beliefs = dict(graph.items())  # defaultdict(...) is faster anyway
    desired = sorted(beliefs.items(), key=itemgetter(0))
    timeslots, diff = [], desired[0][1]
    time = defaultdict(lambda: None)
    for i, (u, v) in enumerate(desired):
        belief = v.count(v.min()) if v.min() in 4, 7 else 0
        time[diff - belief] = i
        beliefs[u].remove(v)

        for j in beliefs[u]:
            if v & j != v:
                diff -= subsumSum(v, j) - subsumSum(v & j, j) - subsumSum(v, j & v)
                if diff in timeslots:
                    start, end = timeslots[diff]
                    return end - start
                timeslots.append(diff)

    return -1

