def get_xor_tree(graph):
    n = len(graph)
    tree = [None] * n

    def dfs(node = 0, parent = None):
        root = node
        left, right = -1, -1
        for child in range(n):
            if graph[child][node]:
                nex, left = dfs(child, node)
                if left == -1:
                    left = child
                elif right != -1:
                    right = child
                else:
                    right = nex
        tree[root] = left, right

        return right, node

    max_node = 0
    for child in range(n):
        nex, node = dfs(child)
        if nex > max_node:
            max_node = nex

    def find_even_suffix(root = max_node):
        parent_dict = {max_node: None}
        even = [max_node]
        stack_root = root
        while even[0] != stack_root:
            parent_dict[even[0]] = stack_root
            stack_root = even[-1] if len(odd) % 4 == 0 else even.pop()
            even.extend(tree[stack_root])
        # we get the depth of the even nodes
        depth = 2 ** int(math.log(max_node, 2)) + 1
        for node in even[1::4]:
            depth += depth // 2

        return depth

    return find_even_suffix()

