def permanent_mod_1000000007(n, k, elements):
    # Initialize the result as 0 (permanent)
    result = 0

    # If the matrix is a 1×1, then the permanent is 1
    if n == 1:
        return 1

    # Iterate over all possible k edges
    for i in range(n):
        for j in range(n):
            if (i, j) in elements:
                continue  # Skip if the element is already present in the matrix

            # Calculate the value for the permanent
            value = 1
            for x in range(n):
                for y in range(n):
                    if x != i and y != j and (x, y) not in elements:
                        value *= 1  # 1 if element is absent, 1000000007% if element is present

            # Add the value to the result if the element is not already present
            if (i, j) not in elements:
                result += value % 1000000007

    return result % 1000000007

