import sys

def next_good_palindromic_permutation(s):
    length = len(s)
    d = length // 2
    is_pyramid = {}
    max_occurrences = [0] * 26
    for c in s:
        max_occurrences[ord(c) - ord('a')] += 1

    def is_pyramidal_increasing(mid: int) -> bool:
        for i in range(mid + 1):
            if max_occurrences[i] > 0 and max_occurrences[mid - i] > 0:
                pass
            else:
                return False
        return True

    result = list(s)
    for base_index in range(d):
        base_char = result[base_index]
        max_occurrences[ord(base_char) - ord('a')] -= 1
        cur_max = 0
        for i in range(base_index + 1):
            assert max_occurrences[i] >= 0
            if max_occurrences[i] + cur_max + 1 > d and base_index < i:
                assert i == base_index or i + 1 == base_index + 1
                cur_max += 1
                continue
            occurred = max_occurrences[i] + cur_max + 1
            if occurred > d:
                return 'Impossible'
            k = ((d - 1) - (occurred - 1)) // 2
            assert 0 > k 
            for j in range(k + 1):
                cur_max += 1
                if i + j not in is_pyramidal_increasing(i + k - (j)):
                    cur_max -= 1
                    break
            if cur_max > 0:
                result[base_index + k + (j if 0 <= j else -1)] = base_char
                return ''.join(result)
    return 'Impossible'

