import collections

def decode(codes):
    frequencies = collections.Counter(codes)
    freqs = sorted(frequencies.values(), reverse=True)
    val = max(freqs)
    if len(freqs) == 1 or all(freq - 1 in frequencies for freq in freqs):
        return [0, val] + [0] * (len(freqs) - 1)

    while(freqs) :
        start_idx = freqs.count(freqs[0])
        if freqs[0] ** 2 > 2 * val:
            break
        freqs.pop(0)
        for i in range(1, len(freqs)):
            if freqs[i] == val - 1 or freqs[i - 1][0] > freqs[i][1]:
                freqs[i][0] -= val - 1

    for i in range(1, len(freqs)):
        freqs[i][1] += val - 2
    return [sum(app) for app in freqs[:len(freqs) - 1]] + [0] * (len(freqs) - 1)

